import fitz, os
base_dir = '/filesystem/final_batch4__mechanical_task3_ct_heat_lcc__blind'

def search_pdf(path, keywords):
    print(f'=== Searching {path} ===')
    doc = fitz.open(os.path.join(base_dir, path))
    for page in doc:
        text = page.get_text()
        for kw in keywords:
            if kw.lower() in text.lower():
                print(f'Page {page.number} matches \"{kw}\":')
                lines = [line for line in text.split('\n') if kw.lower() in line.lower()]
                for l in lines[:5]:
                    print(f'   {l}')

