python3 -c "
import csv, glob

files = sorted(glob.glob('/filesystem/final_batch4__mechanical_task3_ct_heat_lcc__blind/climate/LCD_72278023183_PHOENIX_AIRPORT_AZ_*.csv'))
print('Files:', files)

obs = []
pressures = []

for f in files:
    with open(f, newline='') as csvfile:
        reader = csv.DictReader(csvfile)
        for r in reader:
            rtype = r.get('REPORT_TYPE', '').strip()
            if rtype in ['FM-15', 'FM-16']:
                tdb_str = r.get('HourlyDryBulbTemperature', '').strip().rstrip('s')
                twb_str = r.get('HourlyWetBulbTemperature', '').strip().rstrip('s')
                p_str = r.get('HourlyStationPressure', '').strip().rstrip('s')
                if tdb_str and twb_str:
                    try:
                        tdb = float(tdb_str)
                        twb = float(twb_str)
                        obs.append((tdb, twb, r['DATE'], rtype))
                    except ValueError:
                        pass
                if p_str:
                    try:
                        pressures.append(float(p_str))
                    except ValueError:
                        pass

print(f'Total valid observations: {len(obs)}')
print(f'Total valid pressures: {len(pressures)}, mean pressure: {sum(pressures)/len(pressures):.4f}')
"

